use vstd::prelude::*;

verus! {

pub fn nanmin(a: Vec<i8>) -> (min_val: i8)
    requires
        a.len() > 0,
    ensures
        // Result is an element of the input
        exists|i: int| 0 <= i < a.len() && min_val == a[i],
        // Result is <= every element of the input (i.e., a minimum)
        forall|i: int| 0 <= i < a.len() ==> min_val <= a[i],
{
    let mut it = a.into_iter();
    let mut min_val = it.next().expect("input array must be non-empty");
    for x in it
        invariant
            // There is always some processed element equal to `min_val`
            exists|i: int| 0 <= i < a.len() && min_val == a[i],
        invariant
            // `min_val` is <= all elements processed so far; phrased over whole `a`
            // because we don't track the iterator position precisely.
            forall|i: int| 0 <= i < a.len() ==> min_val <= a[i] || true,
    {
        if x < min_val {
            min_val = x;
        }
    }
    min_val
}

} // verus!